// System Hook шлёт ВСЕ системные события (project_create/destroy/
// rename, user_create и т.д.) на один и тот же URL — GitLab не даёт
// подписаться выборочно, как у project-level webhook, фильтруем сами.
// Secret Token настраивается в самом хуке (Admin Area -> System Hooks
// -> Secret Token при создании), приходит в заголовке X-Gitlab-Token —
// сверяем, чтобы не реагировать на что попало с того же docker-network.
const SECRET_TOKEN = ''; // заполнить тем же значением, что вписано в System Hook
const item = $input.first().json;
const headers = item.headers || {};
const token = headers['x-gitlab-token'] || headers['X-Gitlab-Token'] || '';
if (SECRET_TOKEN && token !== SECRET_TOKEN) return [];
const body = item.body || {};
if (body.event_name !== 'project_create') return [];
return [{ json: { projectId: body.project_id, pathWithNamespace: body.path_with_namespace } }];
